#pragma once

#include "fe/core/Types.h"

#include <vector>

namespace fe {

// The icon a window shows in its title bar and its task-bar entry.
//
// A window is the first thing anyone sees of a running engine, and an OS default
// icon there is a small but real "unfinished" signal. This is the project's own
// mark, expanded from the 1-bit mask generated by tools/gen_engine_icon.py (see
// branding/). It is a plain RGBA buffer so the platform layer can hand it to a
// window backend without the engine depending on an image library: the mask is
// monochrome, so it is stored as bits and tinted here.
//
// The mark is the same geometry as the README banner and the AppImage icon; only
// the ink differs, so it reads on a light or a dark title bar.
class WindowIcon {
public:
    // An empty icon: a backend leaves whatever the OS gave the window. This is
    // the "no icon" value, and the state a default-constructed icon is in.
    WindowIcon() = default;

    // The mark in white - the default for the dark title bars and task bars that
    // both GNOME and Windows use.
    [[nodiscard]] static WindowIcon white();

    // The mark in black - for a light title bar or task bar.
    [[nodiscard]] static WindowIcon black();

    // The mark in an arbitrary ink.
    [[nodiscard]] static WindowIcon mark(u8 r, u8 g, u8 b);

    // Square, RGBA8, row-major, top row first. Empty means "no icon", in which
    // case a backend leaves whatever the OS gave the window.
    [[nodiscard]] const std::vector<u8>& pixels() const noexcept { return pixels_; }
    [[nodiscard]] u32 width() const noexcept { return width_; }
    [[nodiscard]] u32 height() const noexcept { return height_; }
    [[nodiscard]] bool empty() const noexcept { return pixels_.empty(); }

    // The mark is square and this many pixels on a side.
    static constexpr u32 kEdge = 64;

private:
    WindowIcon(u8 r, u8 g, u8 b);

    std::vector<u8> pixels_;
    u32 width_ = 0;
    u32 height_ = 0;
};

} // namespace fe
